import threading

class WebhookDeduplicator:
    def __init__(self):
        self._entities = {}
        self._lock = threading.Lock()

    def process_event(self, event: dict) -> dict:
        # Validation
        required_fields = ['idempotency_key', 'entity_id', 'event_ts', 'version', 'payload']
        for field in required_fields:
            if field not in event:
                return {
                    "status": "INVALID",
                    "current_state": None,
                    "applied_version": None
                }

        idempotency_key = event['idempotency_key']
        entity_id = event['entity_id']
        event_ts = event['event_ts']
        version = event['version']
        payload = event['payload']

        # Type checks - must be int and not bool
        if not isinstance(idempotency_key, str) or idempotency_key == "":
            return {"status": "INVALID", "current_state": None, "applied_version": None}
        if not isinstance(entity_id, str) or entity_id == "":
            return {"status": "INVALID", "current_state": None, "applied_version": None}
        if not isinstance(event_ts, int) or isinstance(event_ts, bool):
            return {"status": "INVALID", "current_state": None, "applied_version": None}
        if not isinstance(version, int) or isinstance(version, bool):
            return {"status": "INVALID", "current_state": None, "applied_version": None}
        if not isinstance(payload, dict):
            return {"status": "INVALID", "current_state": None, "applied_version": None}

        # Check if idempotency_key has been seen
        with self._lock:
            if idempotency_key in self._entities:
                # Get current state and applied version
                entity = self._entities[idempotency_key]
                current_state = entity.get('current_state')
                applied_version = entity.get('applied_version')
                return {
                    "status": "DUPLICATE",
                    "current_state": current_state,
                    "applied_version": applied_version
                }

        # Entity not seen before - initialize with defaults
        with self._lock:
            # Initialize entity if not present
            if idempotency_key not in self._entities:
                self._entities[idempotency_key] = {
                    'last_ts': -1,
                    'last_version': -1,
                    'current_state': None,
                    'applied_version': None
                }

            entity = self._entities[idempotency_key]
            last_ts = entity['last_ts']
            last_version = entity['last_version']
            current_state = entity['current_state']
            applied_version = entity['applied_version']

        # Causal ordering check
        if (event_ts, version) > (last_ts, last_version):
            # Valid update - apply the event
            entity['current_state'] = dict(payload)
            entity['last_ts'] = event_ts
            entity['last_version'] = version
            entity['applied_version'] = version
            # Mark as seen
            self._entities[idempotency_key]['seen'] = True
            return {
                "status": "APPLIED",
                "current_state": dict(payload),
                "applied_version": version
            }
        else:
            # Stale event - mark as seen so future duplicates are also ignored
            self._entities[idempotency_key]['seen'] = True
            return {
                "status": "STALE_IGNORED",
                "current_state": current_state,
                "applied_version": applied_version
            }
